-- FoodBridge development schema. Run against a NEW nonprofit_db database.
-- PostgreSQL. Child tables reference users with the matching account role (enforced by services in Phase 1).
BEGIN;
CREATE TABLE IF NOT EXISTS areas(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,city VARCHAR(100) NOT NULL,district VARCHAR(100) NOT NULL,UNIQUE(city,district));
CREATE TABLE IF NOT EXISTS users(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,name VARCHAR(150) NOT NULL,email VARCHAR(255) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,phone VARCHAR(40),address TEXT,area_id BIGINT REFERENCES areas(id),role VARCHAR(30) NOT NULL CHECK(role IN ('DONOR','VOLUNTEER','BENEFICIARY','ADMIN')),is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS donors(user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,donor_type VARCHAR(30),organization_name VARCHAR(150));
CREATE TABLE IF NOT EXISTS volunteers(user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,availability VARCHAR(150),has_transport BOOLEAN NOT NULL DEFAULT FALSE,total_hours DOUBLE PRECISION NOT NULL DEFAULT 0 CHECK(total_hours>=0));
CREATE TABLE IF NOT EXISTS beneficiaries(user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,household_size INTEGER CHECK(household_size>0),needs TEXT);
CREATE TABLE IF NOT EXISTS admins(user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS admin_permissions(admin_id BIGINT NOT NULL REFERENCES admins(user_id) ON DELETE CASCADE,permission VARCHAR(100) NOT NULL,PRIMARY KEY(admin_id,permission));
CREATE TABLE IF NOT EXISTS event_types(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS food_categories(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS units(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,name VARCHAR(50) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS donation_statuses(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,name VARCHAR(50) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS donations(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,donor_id BIGINT NOT NULL REFERENCES donors(user_id),area_id BIGINT REFERENCES areas(id),donation_date DATE NOT NULL DEFAULT CURRENT_DATE,status_id BIGINT NOT NULL REFERENCES donation_statuses(id),donation_type VARCHAR(10) NOT NULL CHECK(donation_type IN ('MONEY','FOOD')));
CREATE TABLE IF NOT EXISTS money_donations(donation_id BIGINT PRIMARY KEY REFERENCES donations(id) ON DELETE CASCADE,amount NUMERIC(14,2) NOT NULL CHECK(amount>0),method VARCHAR(30) NOT NULL,transaction_id VARCHAR(150),paid BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS food_donations(donation_id BIGINT PRIMARY KEY REFERENCES donations(id) ON DELETE CASCADE,expiry_date DATE,pickup_window VARCHAR(150));
CREATE TABLE IF NOT EXISTS food_items(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,food_donation_id BIGINT NOT NULL REFERENCES food_donations(donation_id) ON DELETE CASCADE,name VARCHAR(150) NOT NULL,quantity NUMERIC(14,3) NOT NULL CHECK(quantity>0),category_id BIGINT NOT NULL REFERENCES food_categories(id),unit_id BIGINT NOT NULL REFERENCES units(id),allergens TEXT,expiry_date DATE);
CREATE TABLE IF NOT EXISTS receipts(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,donation_id BIGINT NOT NULL UNIQUE REFERENCES donations(id),receipt_number VARCHAR(100) NOT NULL UNIQUE,issue_date DATE NOT NULL DEFAULT CURRENT_DATE);
CREATE TABLE IF NOT EXISTS events(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,title VARCHAR(200) NOT NULL,description TEXT,event_date TIMESTAMPTZ NOT NULL,location VARCHAR(200),event_type_id BIGINT NOT NULL REFERENCES event_types(id));

ALTER TABLE events
    ADD COLUMN IF NOT EXISTS status VARCHAR(20)
    NOT NULL DEFAULT 'SCHEDULED';

CREATE TABLE IF NOT EXISTS event_registrations(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,event_id BIGINT NOT NULL REFERENCES events(id) ON DELETE CASCADE,volunteer_id BIGINT NOT NULL REFERENCES volunteers(user_id),registered_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),attendance_status VARCHAR(40) NOT NULL DEFAULT 'REGISTERED',UNIQUE(event_id,volunteer_id));
CREATE TABLE IF NOT EXISTS pickup_tasks(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,food_donation_id BIGINT NOT NULL REFERENCES food_donations(donation_id),volunteer_id BIGINT REFERENCES volunteers(user_id),beneficiary_id BIGINT REFERENCES beneficiaries(user_id),pickup_time TIMESTAMPTZ,delivery_time TIMESTAMPTZ,status VARCHAR(30) NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','ASSIGNED','PICKED_UP','DELIVERED','CANCELLED')),hours_spent DOUBLE PRECISION NOT NULL DEFAULT 0 CHECK(hours_spent>=0));
CREATE TABLE IF NOT EXISTS donation_requests(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,beneficiary_id BIGINT NOT NULL REFERENCES beneficiaries(user_id),category_id BIGINT NOT NULL REFERENCES food_categories(id),unit_id BIGINT NOT NULL REFERENCES units(id),quantity NUMERIC(14,3) NOT NULL CHECK(quantity>0),request_date DATE NOT NULL DEFAULT CURRENT_DATE,status VARCHAR(40) NOT NULL DEFAULT 'PENDING');
CREATE TABLE IF NOT EXISTS distributions(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,food_donation_id BIGINT NOT NULL REFERENCES food_donations(donation_id),beneficiary_id BIGINT NOT NULL REFERENCES beneficiaries(user_id),volunteer_id BIGINT REFERENCES volunteers(user_id),pickup_task_id BIGINT REFERENCES pickup_tasks(id),distribution_date DATE NOT NULL DEFAULT CURRENT_DATE,quantity NUMERIC(14,3) NOT NULL CHECK(quantity>0));
CREATE TABLE IF NOT EXISTS notifications(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,recipient_user_id BIGINT NOT NULL REFERENCES users(id),message TEXT NOT NULL,status VARCHAR(40) NOT NULL DEFAULT 'PENDING',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
-- Volunteer module
CREATE TABLE IF NOT EXISTS volunteer_skills(volunteer_id BIGINT NOT NULL REFERENCES volunteers(user_id) ON DELETE CASCADE,skill VARCHAR(100) NOT NULL,PRIMARY KEY(volunteer_id,skill));
CREATE TABLE IF NOT EXISTS volunteer_preferences(volunteer_id BIGINT NOT NULL REFERENCES volunteers(user_id) ON DELETE CASCADE,preference VARCHAR(100) NOT NULL,PRIMARY KEY(volunteer_id,preference));
CREATE TABLE IF NOT EXISTS volunteer_hours(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,volunteer_id BIGINT NOT NULL REFERENCES volunteers(user_id) ON DELETE CASCADE,hours DOUBLE PRECISION NOT NULL CHECK(hours>0),source VARCHAR(20) NOT NULL CHECK(source IN ('PICKUP','EVENT','MANUAL')),note VARCHAR(255),logged_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS certificates(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,volunteer_id BIGINT NOT NULL REFERENCES volunteers(user_id) ON DELETE CASCADE,certificate_number VARCHAR(50) NOT NULL UNIQUE,certificate_type VARCHAR(20) NOT NULL CHECK(certificate_type IN ('PARTICIPATION','ACHIEVEMENT')),hours_at_issue DOUBLE PRECISION NOT NULL,issued_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
ALTER TABLE events ADD COLUMN IF NOT EXISTS required_skill VARCHAR(100);
ALTER TABLE pickup_tasks ADD COLUMN IF NOT EXISTS required_skill VARCHAR(100);
COMMIT;
